planned!("operation-exchange" => cantrip_mechanics::exchange::exchange(g, asker.source, Exchange::Control, { let q: &dyn Query = g; selected_1.clone() }, { let q: &dyn Query = g; t_1_raw.get(0).copied().filter(|t| t_1.contains(t)).and_then(|t: Target| t.player()) }, None));
